<script setup lang="ts">
import { reactive,ref,computed,onMounted,onUnmounted,watch,nextTick } from 'vue'
import { useBistro } from './store'
import { stages,labels,asset,defaults,type Settings,type Stage } from './model'
import Icon from './components/Icon.vue'
import RestaurantScene from './components/RestaurantScene.vue'
const b=reactive(useBistro())
const form=reactive<Settings>({...defaults}),formToken=ref(''),clearToken=ref(false),saving=ref(false),saveError=ref(''),query=ref(''),visibleCount=ref(60),focusReturn=ref<HTMLElement|null>(null)
const modal=ref<HTMLElement>(),formModal=ref<HTMLElement>()
const filtered=computed(()=>{if(!b.drawer)return [];const q=query.value.trim().toLowerCase();return b.groups[b.drawer].filter(x=>`${x.id} ${x.title} ${x.assignee}`.toLowerCase().includes(q))})
const formattedDate=computed(()=>b.now.toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'}))
const selected=computed(()=>b.drawer?labels[b.drawer]:null)
const time=(value?:Date|string)=>value?new Date(value).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'尚未同步'
watch(()=>b.drawer,async()=>{query.value='';visibleCount.value=60;if(b.drawer){focusReturn.value=document.activeElement as HTMLElement;await nextTick();modal.value?.querySelector<HTMLInputElement>('input')?.focus()}else focusReturn.value?.focus()})
watch(()=>b.settingsOpen,async open=>{if(open){focusReturn.value=document.activeElement as HTMLElement;Object.assign(form,b.settings);formToken.value='';clearToken.value=false;saveError.value='';await nextTick();formModal.value?.querySelector<HTMLElement>('button')?.focus()}else focusReturn.value?.focus()})
async function save(){saving.value=true;saveError.value='';try{await b.saveSettings({...form},clearToken.value?'':formToken.value||undefined)}catch(e){saveError.value=e instanceof Error?e.message.replace(/^Error invoking remote method '[^']+': (Error: )?/,''):'设置保存失败'}finally{saving.value=false}}
async function toggleDemo(){try{await b.saveSettings({...b.settings,autoDemo:!b.settings.autoDemo})}catch{b.toast('演示设置保存失败')}}
function keyboard(e:KeyboardEvent){if(e.key==='Escape'&&!saving.value){b.drawer=null;b.settingsOpen=false}if(e.key==='Tab'&&(b.drawer||b.settingsOpen)){const root=b.settingsOpen?formModal.value:modal.value;const all=root?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]');if(!all?.length)return;const first=all[0]!,last=all[all.length-1]!;if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
let stopModeListener:(()=>void)|undefined
onMounted(()=>{stopModeListener=window.bistro?.onWindowModeChanged(mode=>{b.settings.windowMode=mode;if(mode==='desktop'){b.view='hall';b.settingsOpen=false;b.drawer=null}});void b.init();window.addEventListener('keydown',keyboard)})
onUnmounted(()=>{stopModeListener?.();b.destroy();window.removeEventListener('keydown',keyboard)})
function open(stage:Stage){b.drawer=stage}
</script>
<template>
 <div class="app-shell" :class="{'reduced-motion':!b.settings.animations,frameless:b.settings.windowMode!=='normal',wallpaper:b.settings.windowMode==='desktop'}">
  <div class="titlebar"><div class="titlebar-brand"><Icon name="cup" :size="15"/> BUG BISTRO <span>桌面小餐馆</span></div><div class="window-controls"><button aria-label="最小化" @click="b.windowAction('minimize')"><Icon name="minus" :size="15"/></button><button aria-label="最大化或还原" @click="b.windowAction('maximize')"><Icon name="maximize" :size="13"/></button><button class="window-close" aria-label="退出小餐馆" @click="b.windowAction('close')"><Icon name="close" :size="16"/></button></div></div>
  <aside class="sidebar">
   <div class="brand"><img :src="asset('chef_happy')" alt="小餐馆厨师"><div><strong>Bug 小餐馆</strong><small>A LITTLE PROGRESS, DAILY</small></div></div>
   <div class="nav-label">我的工作日常</div>
   <nav><button :class="{active:b.view==='hall'}" @click="b.view='hall'"><Icon name="home"/><span>餐馆大厅</span><i></i></button><button :class="{active:b.view==='board'}" @click="b.view='board'"><Icon name="board"/><span>订单看板</span><em>{{b.stats.todo+b.stats.doing+b.stats.ready}}</em></button><button @click="b.settingsOpen=true"><Icon name="settings"/><span>餐馆设置</span></button></nav>
   <div class="sidebar-note"><span class="mini-star">✦</span><p>一点点修复，<br>一份份好消息。</p><img :src="asset('prop_plant')" alt="窗边绿植"></div>
   <div class="sidebar-bottom"><div class="source-label"><span :class="{error:!!b.error}"></span>{{b.settings.source==='mock'?'模拟数据 · 可交互演示':'HTTP 数据 · 只读接入'}}</div><small>不修改外部系统的 Bug 状态</small><button @click="b.windowAction(b.settings.windowMode==='desktop'?'restore':'desktop')"><Icon name="desktop" :size="16"/>{{b.settings.windowMode==='desktop'?'恢复普通窗口':'放到桌面'}}<Icon name="arrow" :size="14"/></button></div>
  </aside>
  <div v-if="b.settings.windowMode==='desktop'" class="wallpaper-summary"><small>BUG BISTRO · 营业中</small><h1>一点进度，一点烟火气。</h1><p>{{formattedDate}} · {{time(b.now)}}</p><div><span v-for="stage in stages" :key="stage">{{labels[stage].zone}} <b>{{b.stats[stage]}}</b></span></div><em>托盘 / Ctrl+Shift+B 恢复窗口</em></div>
  <main class="main-content">
   <header class="page-header"><div><div class="eyebrow">{{formattedDate}} <span>/</span> {{b.view==='hall'?'RESTAURANT LIVE':'ORDER BOARD'}}</div><h1>{{b.view==='hall'?'今天的小餐馆':'每一份订单，都有进度'}}<span class="open-pill"><span></span>营业中</span></h1><p>{{b.view==='hall'?'把工作进度变成看得见的烟火气。':'从等待备菜，到热腾腾地送上餐桌。'}}</p></div><div class="header-actions"><button class="icon-button" aria-label="餐馆设置" @click="b.settingsOpen=true"><Icon name="settings"/></button><button class="button secondary" :disabled="b.loading" @click="b.sync()"><Icon name="refresh" :class="{spin:b.loading}" :size="17"/>{{b.loading?'同步中':'重新同步'}}</button><button v-if="b.settings.source==='mock'" class="button primary" data-testid="new-bug" @click="b.add()"><Icon name="plus" :size="18"/>新来一单</button></div></header>
   <div v-if="b.error" class="error-banner" role="alert"><Icon name="warning" :size="19"/><span>{{b.error}}</span><button @click="b.sync()">重试同步 <Icon name="arrow" :size="15"/></button></div>
   <section v-if="b.settings.showStats" class="stats-grid" aria-label="Bug 状态统计">
    <button v-for="(stage,index) in stages" :key="stage" class="stat-card" :class="stage" :data-testid="`stat-${stage}`" @click="open(stage)"><div class="stat-heading"><span class="stat-dot" :style="{background:labels[stage].color}"></span>{{labels[stage].name}}<Icon name="chevron" :size="15"/></div><div class="stat-value"><strong :data-testid="`count-${stage}`">{{b.stats[stage]}}</strong><span>笔订单</span><img :src="asset(labels[stage].dish)" alt=""></div><div class="stat-foot"><span>0{{index+1}}</span>{{labels[stage].zone}}</div></button>
   </section>
   <template v-if="b.view==='hall'||b.settings.windowMode==='desktop'">
    <section class="scene-card"><div class="section-bar"><div><span class="live-dot"></span><h2>餐馆实况</h2><span class="section-subtitle">好好做菜，认真修 Bug</span></div><div class="scene-status"><Icon name="sun" :size="17"/><span>{{b.chefMood==='panic'?'订单积压 · 加紧出餐':b.chefMood==='busy'?'有点忙碌 · 有条不紊':'今日天气 · 适合开工'}}</span></div></div>
     <RestaurantScene :stats="b.stats" :mood="b.chefMood" :animated="b.settings.animations" :activity="b.activities[0]?.text||''" @open="open"/>
     <div class="scene-legend"><span><Icon name="search" :size="14"/>点击场景中的区域，看看对应订单</span><div><span class="legend-item"><i class="dot todo"></i>等待做</span><Icon name="arrow" :size="13"/><span class="legend-item"><i class="dot doing"></i>正在做</span><Icon name="arrow" :size="13"/><span class="legend-item"><i class="dot ready"></i>待上桌</span><Icon name="arrow" :size="13"/><span class="legend-item"><i class="dot closed"></i>已上桌</span></div></div>
    </section>
    <div class="below-scene">
     <section class="activity-card"><div class="section-bar"><div><Icon name="clock" :size="17"/><h2>营业小记</h2></div><span class="muted">最近的好消息</span></div><div class="activity-list"><div v-for="item in b.activities.slice(0,3)" :key="item.id" class="activity-item"><span class="activity-dot" :style="{background:item.stage?labels[item.stage].color:'#a8ac9b'}"></span><p>{{item.text}}</p><time>{{item.time}}</time></div><p v-if="!b.activities.length" class="empty-inline">正在准备开门营业…</p></div></section>
     <section class="daily-card"><div class="daily-heading"><Icon name="leaf" :size="20"/><span>今日的小小成就</span></div><div class="daily-number">{{b.stats.closed}}<small>份订单已上桌</small></div><div class="progress-track"><span :style="{width:`${b.progress}%`}"></span></div><p>今日可见订单完成率 <strong>{{b.progress}}%</strong></p></section>
    </div>
   </template>
   <section v-else class="kanban"><div v-for="stage in stages" :key="stage" class="kanban-column"><div class="kanban-heading"><i :style="{background:labels[stage].color}"></i><h2>{{labels[stage].zone}}</h2><span>{{b.stats[stage]}}</span></div><div v-for="bug in b.groups[stage].slice(0,20)" :key="bug.id" class="order-card"><div class="order-top"><small>{{bug.id}}</small><span class="priority" :class="bug.priority">{{bug.priority==='high'?'优先处理':bug.priority==='low'?'低优先级':'普通'}}</span></div><h3>{{bug.title}}</h3><div class="order-bottom"><span class="avatar">{{bug.assignee.slice(0,1)}}</span><span>{{bug.assignee}}</span><button v-if="stage!=='closed'&&b.settings.source==='mock'" :aria-label="`${bug.id} ${labels[stage].verb}`" @click="b.advance(bug.id)"><Icon name="arrow" :size="17"/></button><Icon v-else-if="stage==='closed'" name="check" :size="17"/></div></div><div v-if="!b.groups[stage].length" class="kanban-empty"><img :src="asset('prop_plates')" alt="">这里暂时没有订单</div><button class="text-button" @click="open(stage)">查看全部 {{b.stats[stage]}} 单 <Icon name="arrow" :size="14"/></button></div></section>
   <section v-if="b.settings.source==='mock'" class="demo-toolbar" aria-label="模拟数据操作"><div><span class="demo-label">MOCK</span><span>用模拟订单，体验小餐馆的一天</span></div><div><button :aria-label="b.settings.autoDemo?'暂停自动演示':'继续自动演示'" @click="toggleDemo"><Icon :name="b.settings.autoDemo?'pause':'play'" :size="15"/>{{b.settings.autoDemo?'暂停演示':'继续演示'}}</button><button data-testid="advance-one" @click="b.advance()"><Icon name="arrow" :size="15"/>推进一单</button><button data-testid="stress" @click="b.add(14)">模拟忙碌</button><button @click="b.simulateFailure()">模拟断网</button><button @click="b.reset()">重置</button></div></section>
   <footer class="page-footer"><span><span class="connection-dot" :class="{error:b.error}"></span>{{b.loading?'正在同步':b.error?'同步异常 · 进度已保留':'一切正常，慢慢来就好'}}<span class="footer-divider">|</span>最后同步 {{time(b.lastSync)}}</span><span>Bug Bistro <span class="footer-divider">/</span> v1.1.0</span></footer>
  </main>
  <Transition name="toast"><div v-if="b.notice" class="toast-notice" role="status"><Icon name="check" :size="18"/>{{b.notice}}</div></Transition>
  <div v-if="b.drawer" class="modal-scrim" @click.self="b.drawer=null"><aside ref="modal" class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header><div><small>订单详情 / {{labels[b.drawer].zone}}</small><h2 id="drawer-title">{{selected?.name}}<span>{{b.stats[b.drawer]}}</span></h2></div><button class="icon-button" aria-label="关闭订单列表" @click="b.drawer=null"><Icon name="close"/></button></header><p class="drawer-hint">{{selected?.hint}}</p><div class="search-field"><Icon name="search" :size="17"/><input v-model="query" placeholder="搜索编号、标题或负责人" aria-label="搜索订单"></div><div class="drawer-list"><article v-for="bug in filtered.slice(0,visibleCount)" :key="bug.id" class="detail-order" data-testid="drawer-order"><div class="order-top"><small>{{bug.id}}</small><span class="priority" :class="bug.priority">{{bug.priority==='high'?'优先处理':bug.priority==='low'?'低优先级':'普通'}}</span></div><h3>{{bug.title}}</h3><div class="detail-meta"><span class="avatar">{{bug.assignee.slice(0,1)}}</span><span>{{bug.assignee}}</span><time>更新于 {{time(bug.updatedAt)}}</time></div><button v-if="bug.status!=='closed'&&b.settings.source==='mock'" class="order-advance" :aria-label="`${bug.id} ${labels[bug.status].verb}`" @click="b.advance(bug.id)">{{labels[bug.status].verb}}<Icon name="arrow" :size="15"/></button></article><button v-if="filtered.length>visibleCount" class="button secondary load-more" @click="visibleCount+=60">继续查看（剩余 {{filtered.length-visibleCount}} 条）</button><div v-if="!filtered.length" class="drawer-empty"><img :src="asset('prop_plates')" alt="空餐盘"><h3>{{query?'没有找到匹配订单':'这里暂时没有订单'}}</h3><p>{{query?'换个关键词试试看。':'小餐馆会随着工作进度慢慢变化。'}}</p></div></div><footer>共 {{filtered.length}} 笔{{b.drawer==='closed'?'今日关闭的':''}}订单 · {{b.settings.source==='mock'?'模拟操作仅影响本地示例':'数据源为只读，不会修改外部状态'}}</footer></aside></div>
  <div v-if="b.settingsOpen" class="modal-scrim settings-scrim" @click.self="!saving&&(b.settingsOpen=false)"><section ref="formModal" class="settings-dialog" role="dialog" aria-modal="true" aria-labelledby="settings-title"><header><div><small>MAKE YOURSELF AT HOME</small><h2 id="settings-title">餐馆设置</h2></div><button class="icon-button" aria-label="关闭设置" :disabled="saving" @click="b.settingsOpen=false"><Icon name="close"/></button></header><form @submit.prevent="save"><div class="settings-body"><h3>场景与演示</h3><label class="switch-row"><span><b>场景动画</b><small>角色走动、烹饪与蒸汽；关闭后仍正常更新数据</small></span><input v-model="form.animations" type="checkbox" role="switch" data-testid="animation-toggle"></label><label class="switch-row"><span><b>显示状态统计栏</b><small>隐藏后，仍可点击场景区域查看订单</small></span><input v-model="form.showStats" type="checkbox" role="switch"></label><label class="switch-row"><span><b>自动演示</b><small>Mock 模式下，每 8 秒自动新增或推进订单</small></span><input v-model="form.autoDemo" type="checkbox" role="switch"></label><div class="settings-pair"><label>忙碌阈值<input v-model.number="form.threshold" type="number" min="1" max="999" required><small>待处理 + 处理中达到阈值时加快；两倍时忙乱</small></label><label>刷新间隔（秒）<input v-model.number="form.refreshSeconds" type="number" min="5" max="3600" required></label></div><h3>桌面窗口</h3><div class="settings-pair"><label>窗口大小<select v-model="form.windowSize"><option value="compact">紧凑 · 1060 × 740</option><option value="normal">舒适 · 1380 × 900</option><option value="large">宽敞 · 1600 × 1000</option></select></label><label>窗口模式<select v-model="form.windowMode"><option value="normal">普通窗口</option><option value="borderless">无边框窗口</option><option value="desktop">桌面背景模式</option></select></label></div><label class="switch-row"><span><b>窗口置顶</b><small>桌面背景模式下不生效</small></span><input v-model="form.alwaysOnTop" type="checkbox" role="switch"></label><p class="settings-note"><Icon name="desktop" :size="16"/>真正挂载到 Windows 桌面图标后方，覆盖当前显示器；失败会明确提示并保留普通窗口。托盘或 Ctrl+Shift+B 恢复。</p><h3>数据源</h3><label class="field-label">接入方式<select v-model="form.source"><option value="mock">Mock · 本地模拟数据</option><option value="http">HTTP · 只读 JSON 接口</option></select></label><template v-if="form.source==='http'"><label class="field-label">接口地址<input v-model.trim="form.endpoint" type="url" placeholder="https://example.com/api/bugs" required><small>远程仅允许 HTTPS，本机可使用 http://127.0.0.1</small></label><label class="field-label">Bearer 令牌（可选）<input v-model="formToken" type="password" autocomplete="off" :placeholder="b.settings.hasToken?'已加密保存；留空保持不变':'无需鉴权可留空'"></label><button v-if="b.settings.hasToken" type="button" class="text-button" @click="clearToken=!clearToken">{{clearToken?'取消清除令牌':'清除已保存令牌'}}</button><div class="api-note">接口返回数组或 <code>{ items: [...] }</code>。字段：<code>id, title, status, updatedAt</code>；可选 <code>assignee, createdAt, priority</code>。关闭状态需提供 <code>closedAt</code>。支持 todo / doing / ready / closed 及文档中的中文状态。</div></template><p v-else class="settings-note">无需凭证即可完整体验；示例进度仅保存在本机，重置不会影响外部系统。</p><div v-if="saveError" class="save-error" role="alert">{{saveError}}</div></div><footer><span>改变数据源不会写入外部系统</span><button type="button" class="button secondary" :disabled="saving" @click="b.settingsOpen=false">取消</button><button class="button primary" type="submit" :disabled="saving" data-testid="save-settings">{{saving?'保存中…':'保存设置'}}</button></footer></form></section></div>
 </div>
</template>
